@startuml

class MACHINE {
  + serialNumber : string
  + make : string
  + model : string
  + purchaseDate : date
}

class WORKER {
  + name : string
  + birthDate : date
  + address : string
  + skills : string[]
}

class PRODUCT_TYPE {
  + material : string
  + weight : float
}

class PRODUCT {
  + id : string
  + name : string
}

class CLIENT {
  + name : string
  + address : string
  + phoneNumber : string
  + contactPerson : string
}

class PURCHASEORDER {
  + orderNumber : string
  + dateMade : date
  + expectedDeliveryDate : date
  + actualDeliveryDate : date
}

class PRODUCTPURCHASEORDER {
  + quantity : int
}

MACHINE "*" -- "*" WORKER : operated by
MACHINE "1" -- "*" PRODUCT_TYPE : produces
PRODUCT_TYPE "1" -- "*" PRODUCT : is of type
CLIENT "1" -- "*" PURCHASEORDER : issues
PURCHASEORDER "1" *-- "*" PRODUCTPURCHASEORDER : contains
PRODUCT "1" -- "*" PRODUCTPURCHASEORDER : is in

@enduml

